const fs = require('fs');

const backupDir = '/home/node/n8n-backups';
if (!fs.existsSync(backupDir)) {
  fs.mkdirSync(backupDir, { recursive: true });
}

const inputJson = $input.first().json;
const workflows = Array.isArray(inputJson) ? inputJson : (inputJson.data || []);

return workflows.map(wf => {
  const safeName = (wf.name || 'unnamed_workflow')
    .replace(/[/\\?%*:|"<>]/g, '_')
    .trim();

  const fileName = `${safeName}_${wf.id}.json`;
  const filePath = `${backupDir}/${fileName}`;

  fs.writeFileSync(filePath, JSON.stringify(wf, null, 2), 'utf8');

  return {
    json: {
      id: wf.id,
      name: wf.name,
      fileName: fileName
    }
  };
});

const workflows = $input.first().json.data;
const results = [];

for (const wf of workflows) {
  // 过滤文件名中的非法字符
  const safeName = wf.name.replace(/[^a-zA-Z0-9_\u4e00-\u9fa5\-]/g, '_');
  const fileName = `${safeName}_${wf.id}.json`;

  results.push({
    json: {
      id: wf.id,
      name: wf.name,
      fileName: fileName,
      // 格式化美化 JSON
      content: JSON.stringify(wf, null, 2)
    }
  });
}

return results;
